-- Ev Görevleri şablon kataloğu (öneri, 23 Ekim 2026). Sözleşme: sozlesme/gorev_sablonlari.md, veri: veri/gorev_sablonlari.json.
-- Herkese aynı katalog: oturum açmış her kullanıcı okur, kimse yazamaz (yalnız göçle değişir). Tekrar çalıştırılabilir.
create table if not exists public.task_templates (
  key text primary key check (key ~ '^[a-z0-9_]{3,60}$'),
  title text not null check (char_length(title) between 1 and 120),
  emoji text not null default '⭐' check (char_length(emoji) <= 16),
  category text not null check (category in ('home','mind','learn','health','focus','relation')),
  categories text[] not null default '{}',
  age_bands text[] not null check (age_bands <@ array['K','A','B','C']::text[] and cardinality(age_bands) > 0),
  difficulty text not null check (difficulty in ('easy','medium','hard')),
  coins int not null check (coins between 0 and 50),
  skill text not null check (skill in ('teamwork','stamina','knowledge','strength','focus','kindness')),
  source_en text,
  sort int not null default 0,
  active boolean not null default true,
  constraint task_templates_skill_matches_category check (
    (category, skill) in (('home','teamwork'),('mind','stamina'),('learn','knowledge'),('health','strength'),('focus','focus'),('relation','kindness'))),
  constraint task_templates_primary_in_tags check (category = any(categories))
);
alter table public.task_templates enable row level security;
drop policy if exists task_templates_read on public.task_templates;
create policy task_templates_read on public.task_templates for select to authenticated using (active);
revoke all on public.task_templates from public, anon;
revoke insert, update, delete on public.task_templates from authenticated;
grant select on public.task_templates to authenticated;
create index if not exists task_templates_category on public.task_templates (category, sort);

-- Süzgeç: kategori (etiketlerde) + yaş grubu (boş = hepsi). Oturum gerekir.
create or replace function public.task_templates_for(p_category text default null, p_band text default null)
returns setof public.task_templates language sql stable security invoker set search_path = public as $$
  select * from public.task_templates t
   where t.active
     and (p_category is null or p_category = any(t.categories))
     and (p_band is null or p_band = any(t.age_bands))
   order by t.sort
$$;
revoke execute on function public.task_templates_for(text, text) from public, anon;
grant execute on function public.task_templates_for(text, text) to authenticated;

on conflict (key) do update set title = excluded.title, emoji = excluded.emoji, category = excluded.category,
  categories = excluded.categories, age_bands = excluded.age_bands, difficulty = excluded.difficulty, coins = excluded.coins,
  skill = excluded.skill, source_en = excluded.source_en, sort = excluded.sort;
